Ltac prove_inside_ibW :=
  first [ cbn [inside]; simpl_sizes; slia
        | simpl_sizes; apply inside_ibW_frame; lia
        | simpl_sizes;
          match goal with
          | H : ?x ∈ ?X |- inside (ibW _ _ ?X) _ _ => apply (inside_ibW_node _ _ _ x _ _ H); lia
          end ].

Ltac footprint_after_store segs m a bs ::=
  repeat match goal with
  | MU : munch ?Wq ?mq m |- _ =>
      first [ apply (munch_write Wq mq m a bs) in MU; [ | lia | simpl_sizes; slia | prove_inside_ibW ]
            | fail 100 "store outside the declared footprint:" a ]
  | WMo : wmono segs ?mq m |- _ => apply (wmono_write segs mq m (wa a) bs) in WMo
  | STq : stk segs m ?loq ?hiq |- _ =>
      first [ apply (stk_write segs m loq hiq a bs) in STq; [ | lia | simpl_sizes; slia ]
            | fail 100 "cannot transport stk hypothesis" STq ]
  end.

(* [comment removed for export] *)
Ltac nnode NSRH L CH :=
  let WF := fresh "WF" in let IN := fresh "IN" in let OUT := fresh "OUT" in let pad := fresh "pad" in let B := fresh "B" in
  destruct (NSR_node _ _ _ _ _ _ _ NSRH L) as (WF & IN & OUT & [pad CH]);
  unfold node_wf in WF; unfold NodeCells, wz in CH;
  pose proof (rw_cells_bound _ _ _ _ CH) as B; cbn [cells_size csize Nat.add] in B.

(* [comment removed for export] *)
Ltac mred H L :=
  first [ rewrite (get_parent_eq _ _ _ L) in H | rewrite (get_left_eq _ _ _ L) in H | rewrite (get_right_eq _ _ _ L) in H
        | rewrite (get_color_eq _ _ _ L) in H
        | rewrite (set_parent_eq _ _ _ _ L) in H | rewrite (set_left_eq _ _ _ _ L) in H | rewrite (set_right_eq _ _ _ _ L) in H
        | rewrite (set_color_eq _ _ _ _ L) in H ];
  cbn [mbind option_bind] in H.

(* [comment removed for export] *)
Ltac pre_store CH k n ML WL :=
