  [| exfalso; unfold get_parent, get_left, get_right, get_color, set_parent, set_left, set_right, set_color, load, store in H;
     rewrite L in H; cbn [mbind option_bind] in H; discriminate].

(* [comment removed for export] *)
Ltac mstep H L :=
  first [ apply (mb_store _ _ _ _ _ _ _ L) in H | apply (mb_load _ _ _ _ _ _ L) in H
        | apply (m_store_last _ _ _ _ _ _ L) in H | apply (m_load_last _ _ _ _ _ L) in H ];
  cbn [get_field set_field OFF_PARENT OFF_LEFT OFF_RIGHT OFF_COLOR Z.eqb Pos.eqb set_par set_lft set_rgt set_col] in H.

