    let nsv := fresh "ns" in let E := fresh "Ens" in remember nsk as nsv eqn:E; clear E end.

(* [comment removed for export] *)
Ltac nload NSRk H x :=
  lazymatch type of NSRk with NSR _ ?ns _ _ _ =>
    let nd := fresh "nd" in let L := fresh "L" in let CH := fresh "CH" in
    mnode ns x nd L H; mstep H L; nnode NSRk L CH; step; clear CH
  end.

(* [comment removed for export] *)
Ltac nstore NSRk H x k n mk :=
  lazymatch type of NSRk with NSR _ ?ns _ _ _ =>
    let nd := fresh "nd" in let L := fresh "L" in let CH := fresh "CH" in let ML := fresh "ML" in let WL := fresh "WL" in
    mnode ns x nd L H; mstep H L; nnode NSRk L CH; pre_store CH k n ML WL; st1;
    let nd' := eval cbv beta in (mk nd) in
    post_store NSRk L ML WL CH nd' k n; gen_store NSRk; clear L
  end.

